assembly {
let success := staticcall(
gas,
_dest,
add(data, 32),
mload(data),
ret,
64
)
if iszero(success) {
revert(0, 0)
}
}

return (ret[0], ret[1]);
}

bytes4 private constant IS_V28_OR_HIGHER_FUNC_SELECTOR = bytes4(keccak256("isV28OrHigher()"));

